// STATE VARIABLES
let currentPageIndex = 0;
let fontSizeScale = 100;

// DOM ELEMENTS
const pageContent = document.getElementById('page-content');
const currentPageNum = document.getElementById('current-page-num');
const totalPagesNum = document.getElementById('total-pages-num');
const headerChapterTitle = document.getElementById('header-chapter-title');
const btnPrev = document.getElementById('btn-prev');
const btnNext = document.getElementById('btn-next');

const btnToc = document.getElementById('btn-toc');
const btnCloseToc = document.getElementById('btn-close-toc');
const tocDrawer = document.getElementById('toc-drawer');
const tocList = document.getElementById('toc-list');

const btnSettings = document.getElementById('btn-settings');
const btnCloseSettings = document.getElementById('btn-close-settings');
const settingsDrawer = document.getElementById('settings-drawer');
const backdrop = document.getElementById('backdrop');

const themeButtons = document.querySelectorAll('.theme-btn');
const btnFontIncrease = document.getElementById('btn-font-increase');
const btnFontDecrease = document.getElementById('btn-font-decrease');
const fontSizeLabel = document.getElementById('font-size-label');

function initReader() {
  totalPagesNum.textContent = bookPages.length;
  buildToc();
  renderPage(currentPageIndex);
  setupEventListeners();
}

function renderPage(index) {
  const page = bookPages[index];
  pageContent.innerHTML = page.content;
  currentPageNum.textContent = index + 1;
  headerChapterTitle.textContent = page.title;

  btnPrev.disabled = index === 0;
  btnNext.disabled = index === bookPages.length - 1;

  window.scrollTo({ top: 0, behavior: 'smooth' });

  document.querySelectorAll('.toc-item').forEach((item, i) => {
    item.classList.toggle('active', i === index);
  });
}

function buildToc() {
  tocList.innerHTML = '';
  bookPages.forEach((page, i) => {
    const a = document.createElement('a');
    a.classList.add('toc-item');
    a.textContent = `${i + 1}. ${page.title}`;
    a.addEventListener('click', () => {
      currentPageIndex = i;
      renderPage(currentPageIndex);
      closeDrawers();
    });
    tocList.appendChild(a);
  });
}

function setupEventListeners() {
  btnNext.addEventListener('click', () => {
    if (currentPageIndex < bookPages.length - 1) {
      currentPageIndex++;
      renderPage(currentPageIndex);
    }
  });

  btnPrev.addEventListener('click', () => {
    if (currentPageIndex > 0) {
      currentPageIndex--;
      renderPage(currentPageIndex);
    }
  });

  btnToc.addEventListener('click', () => openDrawer(tocDrawer));
  btnCloseToc.addEventListener('click', closeDrawers);
  btnSettings.addEventListener('click', () => openDrawer(settingsDrawer));
  btnCloseSettings.addEventListener('click', closeDrawers);
  backdrop.addEventListener('click', closeDrawers);

  themeButtons.forEach(btn => {
    btn.addEventListener('click', (e) => {
      themeButtons.forEach(b => b.classList.remove('active'));
      e.target.classList.add('active');
      document.body.className = `${e.target.dataset.theme}-theme`;
    });
  });

  btnFontIncrease.addEventListener('click', () => {
    if (fontSizeScale < 150) {
      fontSizeScale += 10;
      updateFontScale();
    }
  });

  btnFontDecrease.addEventListener('click', () => {
    if (fontSizeScale > 80) {
      fontSizeScale -= 10;
      updateFontScale();
    }
  });
}

function updateFontScale() {
  document.documentElement.style.setProperty('--font-scale', `${fontSizeScale}%`);
  fontSizeLabel.textContent = `${fontSizeScale}%`;
}

function openDrawer(drawer) {
  closeDrawers();
  drawer.classList.add('open');
  backdrop.classList.add('show');
}

function closeDrawers() {
  tocDrawer.classList.remove('open');
  settingsDrawer.classList.remove('open');
  backdrop.classList.remove('show');
}

document.addEventListener('DOMContentLoaded', initReader);
